"""Stimulator blocks (stimulator, mb_direction, rf_offset) generated by make_project, on the synthetic tutorial data.
Declares all tables (including the diamond foreign keys on the experiment) and populates the stimulator chain."""
import importlib.util
import os
import uuid
from pathlib import Path

import datajoint as dj
import pytest

pytestmark = pytest.mark.skipif(
    os.environ.get("DJ_TEST_MYSQL") != "1",
    reason="requires the MySQL integration-test service",
)

ROOT = Path(__file__).resolve().parents[2]


@pytest.fixture(scope="module")
def stimulator_schema(dj_test_stores, tmp_path_factory):
    dj.config["database.host"] = os.environ.get("DJ_HOST", "127.0.0.1")
    dj.config["database.port"] = int(os.environ.get("DJ_PORT", "3306"))
    dj.config["database.user"] = os.environ.get("DJ_USER", "root")
    dj.config["database.password"] = os.environ.get("DJ_PASS", "datajoint")
    connection = dj.conn()
    schema_name = f"djimaging_ci_stimulator_{uuid.uuid4().hex[:8]}"

    spec = importlib.util.spec_from_file_location('make_project', ROOT / 'make_project.py')
    make_project = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(make_project)
    module_name = "stimulator_schema"
    blocks = make_project.resolve_blocks(['stimulator', 'mb_direction', 'rf_offset', 'history'])
    text = make_project.build_schema_text(ROOT, blocks, channels=None)
    path = tmp_path_factory.mktemp(module_name) / f'{module_name}.py'
    path.write_text(text, encoding='utf8')
    spec = importlib.util.spec_from_file_location(module_name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)

    from djimaging.utils.dj_utils import activate_schema
    try:
        activate_schema(module.schema, schema_name=schema_name)
        yield module
    finally:
        connection.query(f"DROP DATABASE IF EXISTS `{schema_name}`")


def test_stimulator_pipeline(stimulator_schema, tutorial_data_dir):
    s = stimulator_schema
    experiment_key = {"experimenter": "synthetic"}
    s.UserInfo().upload_user({**experiment_key, "data_dir": str(tutorial_data_dir), "datatype_loc": 0,
                              "animal_loc": 1, "region_loc": 2, "field_loc": 3, "stimulus_loc": 4, "cond1_loc": 5,
                              "cond2_loc": 6, "cond3_loc": 7}, verbose=0)
    s.RawDataParams().add_params(from_raw_data=False, igor_roi_masks="yes", experimenter_list=["synthetic"])
    s.Experiment().rescan_filesystem(restrictions=experiment_key, verboselvl=0)

    # Setup tables before Field: Field and Presentation take delay, scan width and artifact rows from them
    s.Stimulator().add_defaults()
    s.ImagingSetup().add_defaults()
    assert len(s.Stimulator()) == 12 and len(s.ImagingSetup()) == 3
    for table, row_id in [(s.ExperimentStimulator, 'setup3_2023-03-09'), (s.ExperimentImagingSetup, 'setup3')]:
        table().populate(display_progress=False)
        for exp_key in (table().key_source - table().proj()).keys():
            table().add_manual(exp_key, row_id, 'low', 'synthetic data')
        assert len(table()) == len(s.Experiment())
        assert len(table().report_unassigned()) == 0

    s.Field().rescan_filesystem(restrictions=experiment_key, verboselvl=0)
    s.Stimulus().add_movingbar(skip_duplicates=True)
    s.Presentation().populate(display_progress=False)
    assert len(s.Field()) > 0
    for key in s.Presentation().keys():
        delay_s = s.ExperimentStimulator().get_stimulator_delay_s(key)
        assert s.Presentation().recording_setup_kwargs(key)['stimulator_delay'] == delay_s

    s.MovingBarVersion().add_defaults()
    s.MbDirectionMap().populate(display_progress=False)
    rows = s.MbDirectionMap().to_dicts()
    assert len(rows) == len(s.Presentation() & dict(stim_name='movingbar'))
    for row in rows:
        assert row['confidence'] == 'low'  # no QDSpy log files for the synthetic data
        assert 'QDSpy log' in row['reason']
